export function parseExpansionRows() {
  return rows.map((line, index) => {
    const [title, aliases, categoryId, summary, attribution, period, work, doi, relatedTitles, techniqueIds, note] = line.split('|');
    if (!title || !categoryTitles[categoryId] || !summary || !attribution || !period || !work) throw new Error(`Invalid expansion row ${index + 1}: ${title}`);
    return {
      title,
      aliases: aliases.split('~').filter(Boolean),
      summary,
      categoryId,
      categoryTitle: categoryTitles[categoryId],
      relatedTitles: relatedTitles.split('~').filter(Boolean),
      techniqueIds: techniqueIds.split('~').filter(Boolean),
      provenance: {
        status: doi ? '書誌確認済み' : '一部確認',
        attribution,
        period,
        works: [work],
        ...(doi ? { sources: [{ title: '代表研究（DOI）', url: `https://doi.org/${doi}` }] } : {}),
        note: note || '個人差と状況差があり、単独で人や結果を断定するための概念ではありません。',
      },
    };
  });
}
